class Store:
    """A client for a remote key-value store that holds account balances.

    Every method that talks to the server is a generator: `yield from` it. Each `yield` is a network
    round trip, and while a request waits there, other requests run.
    """

    def __init__(self, balances):
        self.balances = dict(balances)
        self.locked = set()

    def get(self, account):
        yield                                   # round trip
        return self.balances[account]

    def set(self, account, value):
        yield                                   # round trip
        self.balances[account] = value

    def debit(self, account, amount):
        """Subtract `amount` if the balance covers it; True if it did. The server checks and writes in one step."""
        yield                                   # round trip
        if self.balances[account] < amount:
            return False
        self.balances[account] -= amount
        return True

    def acquire(self, account):
        """Wait until nobody holds the lock on `account`, then take it. Always pair with release()."""
        while account in self.locked:
            yield                               # held by another request: let the others run
        self.locked.add(account)

    def release(self, account):
        self.locked.remove(account)


def withdraw(store, account, amount):
    """Take `amount` out of `account`. Returns True if the money was withdrawn, False if the balance was too low."""
    balance = yield from store.get(account)
    if balance < amount:
        return False
    yield from store.set(account, balance - amount)
    return True

