from itertools import permutations, product
def finished(value):
    """A request written as an ordinary function has already run: wrap its result as a task that is done at once."""
    return value
    yield
def run_interleaved(requests, script, max_rounds=300):
    """Advance the generators in `requests` one step (one next()) at a time in the order of `script` ("A" is requests[0],
    "B" is requests[1], ...), then keep stepping whatever is left in turn. Returns what each request returned."""
    tasks = [r if hasattr(r, "send") else finished(r) for r in requests]
    results, done = [None] * len(tasks), [False] * len(tasks)

    def step(i):
        try:
            next(tasks[i])
        except StopIteration as stop:
            results[i], done[i] = stop.value, True

    for letter in script:
        i = ord(letter) - ord("A")
        if not done[i]:
            step(i)
    rounds = 0
    while not all(done):
        for i in range(len(tasks)):
            if not done[i]:
                step(i)
        rounds += 1
        if rounds > max_rounds:
            raise AssertionError("the requests never finished: is a lock never released?")
    return results
def serial_outcomes(balance, amounts):
    """Every (results, final balance) you can get by running the withdrawals one at a time, in any order."""
    outcomes = set()
    for order in permutations(range(len(amounts))):
        left, results = balance, [None] * len(amounts)
        for i in order:
            results[i] = left >= amounts[i]
            if results[i]:
                left -= amounts[i]
        outcomes.add((tuple(results), left))
    return outcomes
def outcome(balance, amounts, script):
    """One withdrawal per amount from "alice", stepped in the order of `script`: (results, final balance)."""
    store = Store({"alice": balance})
    results = run_interleaved([withdraw(store, "alice", amount) for amount in amounts], script)
    run_interleaved([withdraw(store, "alice", 0)], "")       # a later request must not be left waiting for a lock nobody released
    return tuple(results), store.balances["alice"]
def complain(balance, amounts, script, got, allowed):
    return AssertionError(
        f"balance {balance}, withdrawals {list(amounts)}, requests stepped in the order {script} (A is the first request, B the second): "
        f"results {list(got[0])}, final balance {got[1]}. Run one at a time, the only possible outcomes are "
        + ", ".join(f"{list(r)} with balance {b}" for r, b in sorted(allowed)))
def same_as_one_at_a_time(balance, amounts, script):
    allowed = serial_outcomes(balance, amounts)
    got = outcome(balance, amounts, script)
    if got not in allowed:
        raise complain(balance, amounts, script, got, allowed)
    return True
def holds_for_every_interleaving(balance, amounts, depth):
    """Try every way of ordering the first `depth` steps of the requests."""
    allowed = serial_outcomes(balance, amounts)
    for script in map("".join, product("ABCD"[:len(amounts)], repeat=depth)):
        got = outcome(balance, amounts, script)
        if got not in allowed:
            raise complain(balance, amounts, script, got, allowed)
    return True

